import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("tree audit", () => {
  test("tree audit", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_cy = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "A"}));
    const c_cy_0 = ui.must(await ui.addClaim(pg_uma, p_cy, {"amount": "1.00"}));
    expect(await ui.claimAction(pg_uma, c_cy_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-cc`);
    await ui.setToday(pg_uma, "2026-03-10");
    const p_cy_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "B"}));
    await ui.setSetting(pg_uma, "parent", `${sheet}-c`);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    const p_cy_3 = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_cy_0_2 = ui.must(await ui.addClaim(pg_uma, p_cy_3, {"amount": "2.00"}));
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    await ui.loadSheet(pg_uma, sheet);
    await ui.expectAuditView(pg_uma, "Cy", [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cy amount=2.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cy grade=C`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-cc by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-cc by=uma name=Cy grade=B`
    ]);
    await ui.expectAuditView(pg_uma, "ada", [
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`
    ]);
    await ui.expectAuditView(pg_uma, "", [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cy amount=2.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cy grade=C`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`
    ]);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.expectAuditView(pg_uma, "cy", [
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-cc by=uma person=Cy claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet}-cc by=uma name=Cy grade=B`
    ]);
    await ui.refresh(pg_uma);
    await ui.expectAudit(`${sheet}-c`, [
      `RATE_SET sheet=${sheet}-c by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=1.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-c by=uma claimed-total=1.00 due-total=1.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet}-c by=uma key=parent value=${sheet}`
    ]);
  });
  test("tree audit scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
